<script lang="ts">import{onMount}from'svelte';import{csrfHeaders,idempotencyKey}from'$lib/api/client';let orgID='',profile:any={},permissions:any={},limitNaira=5000000,days=30,grace=48,message='',busy=false;async function load(){const r=await fetch('/api/v1/organizations',{credentials:'include'});const d=await r.json();orgID=d.organizations?.[0]?.id??'';if(!orgID)return;const q=await fetch(`/api/v1/organizations/${orgID}/onboarding`,{credentials:'include'});const x=await q.json();profile=x.profile??{};permissions=x.permissions??{};if(profile.default_credit_limit_kobo)limitNaira=profile.default_credit_limit_kobo/100;days=profile.default_payment_days||days;grace=profile.default_grace_hours??grace}async function save(){busy=true;const r=await fetch(`/api/v1/organizations/${orgID}/onboarding/credit-policy`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({expected_version:profile.version,credit_limit_kobo:Math.round(limitNaira*100),payment_days:Number(days),grace_hours:Number(grace)})});const d=await r.json().catch(()=>({}));busy=false;message=r.ok?'Your normal sale choices were saved.':d.detail??'We could not save these choices.';if(r.ok)profile=d.profile}onMount(load);</script>
<svelte:head><title>Normal sale settings — Kredit</title></svelte:head><main class="shell workspace form-page"><p class="eyebrow">Settings / Normal sales</p><h1>Choose how new sales should start.</h1><p class="lede">We will fill these in when you add a sale. You can still change them for each customer.</p>{#if message}<p class="notice">{message}</p>{/if}<section class="card">{#if permissions.credit_policy}<label>Most one customer should owe (₦)<input type="number" min="1" bind:value={limitNaira} /></label><label>Normal number of days to pay<input type="number" min="1" max="365" bind:value={days} /></label><label>Extra hours after the payment day<input type="number" min="0" max="720" bind:value={grace} /></label><button disabled={busy||limitNaira<=0} onclick={save}>{busy?'Saving…':'Save these choices'}</button>{:else}<p>You can see these choices, but only the owner or an allowed staff member can change them.</p>{/if}</section><a href="/app/onboarding">← Back to account setup</a></main>
<style>.form-page{max-width:52rem}.form-page h1{font-size:clamp(2.4rem,6vw,4.5rem);line-height:1}.card{display:grid;gap:.8rem;padding:1.4rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}.card label{display:grid;gap:.3rem;font-weight:700}.card input,.card button{padding:.75rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}.card button{background:var(--color-primary);color:white;font-weight:800}.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}</style>
